}

type UserActivitySummary struct {
	DisplayName  string
	ActionType   string
	TotalActions int
	SuccessCount int
	AvgDuration  float64
}

// RegisterUser creates a new user profile and inserts it into the database.
func RegisterUser(o orm.Ormer, username, displayName, email, department, role string) (*UserProfile, error) {
	profile := &UserProfile{
		Username:    username,
		DisplayName: displayName,
		Email:       email,
		Department:  department,
		Role:        role,
	}
	_, err := o.Insert(profile)
	if err != nil {
		return nil, err
	}
	return profile, nil
}

// GenerateUserActivityReport creates an activity report for specified users.
func GenerateUserActivityReport(o orm.Ormer, usernames []string, actionTypeFilter string, startDate, endDate time.Time) ([]UserActivitySummary, error) {
	if len(usernames) == 0 {
		return []UserActivitySummary{}, nil
	}

	placeholders := make([]string, len(usernames))
	for i := range placeholders {
		placeholders[i] = "?"
	}
	inClause := strings.Join(placeholders, ",")

	query := "SELECT u.display_name, a.action_type, " +
		"COUNT(*) AS total_actions, " +
		"SUM(CASE WHEN a.success THEN 1 ELSE 0 END) AS success_count, " +
		"AVG(a.duration_ms) AS avg_duration " +
		"FROM user_activity a JOIN user_profile u ON a.user_id = u.id " +
		"WHERE u.username IN (" + inClause + ")"

	args := make([]interface{}, 0, len(usernames)+3)
	for _, uname := range usernames {
		args = append(args, uname)
	}

	if actionTypeFilter != "" {
		query += " AND a.action_type = ?"
		args = append(args, actionTypeFilter)
	}

	query += " AND a.created_at BETWEEN ? AND ?"
	args = append(args, startDate, endDate)

	query += " GROUP BY u.display_name, a.action_type"

	var summaries []UserActivitySummary
	_, err := o.Raw(query, args...).QueryRows(&summaries)
	if err != nil {
		return nil, err
	}
	if summaries == nil {
		summaries = []UserActivitySummary{}
	}
	return summaries, nil
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	allowedFields := map[string]string{
		"department":   "department",
		"role":         "role",
		"display_name": "display_name",
	}
	column, ok := allowedFields[groupByField]
	if !ok {
		return nil, errors.New("invalid groupByField: must be one of department, role, display_name")
	}

	placeholders := make([]string, len(departments))
	for i := range placeholders {
		placeholders[i] = "?"
	}
	inClause := strings.Join(placeholders, ",")

	query := "SELECT u." + column + " AS group_value, " +
		"COUNT(DISTINCT u.id) AS user_count, " +
		"COUNT(a.id) AS total_activities " +
		"FROM user_profile u LEFT JOIN user_activity a ON u.id = a.user_id " +
		"WHERE u.department IN (" + inClause + ") " +
		"GROUP BY u." + column

	args := make([]interface{}, len(departments))
	for i, d := range departments {
		args[i] = d
	}

	type deptReportRow struct {
		GroupValue      string
		UserCount       int
		TotalActivities int
	}

	var rows []deptReportRow
	_, err := o.Raw(query, args...).QueryRows(&rows)
	if err != nil {
		return nil, err
	}

	result := make([]map[string]interface{}, 0, len(rows))
	for _, r := range rows {
		result = append(result, map[string]interface{}{
			"group_value":      r.GroupValue,
			"user_count":       r.UserCount,
			"total_activities": r.TotalActivities,
		})
	}
	return result, nil
}

