	var params []orm.Params
	_, err := o.Raw(sql, args...).Values(&params)
	if err != nil {
		return nil, err
	}

	// Convert orm.Params to []map[string]interface{} with proper types
	results := make([]map[string]interface{}, 0, len(params))
