		}
		if s, ok := p["total_activities"].(string); ok {
			totalActivities, _ = strconv.Atoi(s)
		}
		m["user_count"] = userCount
		m["total_activities"] = totalActivities

		results = append(results, m)
	}

	return results, nil
}

// Helper function to join strings with a separator
func joinStrings(strs []string, sep string) string {
	if len(strs) == 0 {
		return ""
	}
	result := strs[0]
	for _, s := range strs[1:] {
		result += sep + s
	}
	return result
}

