	rawResults, err := o.Raw(query, args...).Values()
	if err != nil {
		return nil, err
	}
	results := make([]map[string]interface{}, len(rawResults))
	for i, p := range rawResults {
		m := make(map[string]interface{})
		for k, v := range p {
			m[k] = v
		}
		results[i] = m
	}
	if results == nil {
		results = []map[string]interface{}{}
	}
	return results, nil
}

// placeholders returns a string with n "?" separated by commas.
func placeholders(n int) string {
	if n <= 0 {
		return ""
	}
	parts := make([]string, n)
	for i := range parts {
		parts[i] = "?"
	}
	return strings.Join(parts, ",")
}

