// RegisterUser creates a new user profile and inserts it into the database.
func RegisterUser(o orm.Ormer, username, displayName, email, department, role string) (*UserProfile, error) {
	profile := &UserProfile{
		Username:    username,
		DisplayName: displayName,
		Email:       email,
		Department:  department,
		Role:        role,
	}
	// CreatedAt will be populated automatically by auto_now_add
	_, err := o.Insert(profile)
	if err != nil {
		return nil, err
	}
	return profile, nil
}

// GenerateUserActivityReport creates an activity report for specified users.
func GenerateUserActivityReport(o orm.Ormer, usernames []string, actionTypeFilter string, startDate, endDate time.Time) ([]UserActivitySummary, error) {
	if len(usernames) == 0 {
		return []UserActivitySummary{}, nil
	}

	// Build IN clause placeholders
	placeholders := strings.Repeat("?,", len(usernames)-1) + "?"
	query := fmt.Sprintf(
		"SELECT u.display_name, a.action_type, COUNT(*) as total, SUM(CASE WHEN a.success THEN 1 ELSE 0 END) as success_count, AVG(a.duration_ms) as avg_duration "+
			"FROM user_activity a JOIN user_profile u ON a.user_id = u.id "+
			"WHERE u.username IN (%s) AND a.created_at >= ? AND a.created_at <= ?",
		placeholders,
	)

	// Prepare args slice
	args := make([]interface{}, 0, len(usernames)+3)
	for _, uname := range usernames {
		args = append(args, uname)
	}
	args = append(args, startDate, endDate)

	if actionTypeFilter != "" {
		query += " AND a.action_type = ?"
		args = append(args, actionTypeFilter)
	}

	query += " GROUP BY u.display_name, a.action_type"

	var summaries []UserActivitySummary
	if _, err := o.Raw(query, args...).QueryRows(&summaries); err != nil {
		return nil, err
	}
	// Return empty slice instead of nil if no rows
	if summaries == nil {
		summaries = []UserActivitySummary{}
	}
	return summaries, nil
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	// Security: whitelist allowed group fields to avoid SQL injection
	allowedFields := map[string]string{
		"department":   "department",
		"role":         "role",
		"display_name": "display_name",
	}
	column, ok := allowedFields[groupByField]
	if !ok {
		return nil, fmt.Errorf("invalid groupByField: %s, must be one of: department, role, display_name", groupByField)
	}

	placeholders := strings.Repeat("?,", len(departments)-1) + "?"
	query := fmt.Sprintf(
		"SELECT u.%s as group_value, COUNT(DISTINCT u.id) as user_count, COUNT(a.id) as total_activities "+
			"FROM user_profile u LEFT JOIN user_activity a ON u.id = a.user_id "+
			"WHERE u.department IN (%s) GROUP BY u.%s",
		column, placeholders, column,
	)

	args := make([]interface{}, len(departments))
	for i, dep := range departments {
		args[i] = dep
	}

	var rows []DepartmentReportRow
	if _, err := o.Raw(query, args...).QueryRows(&rows); err != nil {
		return nil, err
	}

	result := make([]map[string]interface{}, 0, len(rows))
	for _, row := range rows {
		m := make(map[string]interface{})
		m["group_value"] = row.GroupValue
		m["user_count"] = row.UserCount
		m["total_activities"] = row.TotalActivities
		result = append(result, m)
	}

	return result, nil
}

