// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	validFields := map[string]bool{
		"department":   true,
		"role":         true,
		"display_name": true,
	}
	if !validFields[groupByField] {
		return nil, fmt.Errorf("invalid groupByField: %s", groupByField)
	}

	query := `SELECT u.` + groupByField + ` AS GroupValue, COUNT(DISTINCT u.id) AS UserCount, COUNT(a.id) AS TotalActivities` +
		` FROM user_activity a JOIN user_profile u ON a.user_id = u.id` +
		` WHERE u.department IN (` + placeholders(len(departments)) + `)` +
		` GROUP BY u.` + groupByField

	args := make([]interface{}, len(departments))
	for i, d := range departments {
		args[i] = d
	}

	type reportRow struct {
		GroupValue      string `orm:"column(GroupValue)"`
		UserCount       int64  `orm:"column(UserCount)"`
		TotalActivities int64  `orm:"column(TotalActivities)"`
	}

	var rows []reportRow
	_, err := o.Raw(query, args...).QueryRows(&rows)
	if err != nil {
		return nil, err
	}

	result := make([]map[string]interface{}, len(rows))
	for i, r := range rows {
		result[i] = map[string]interface{}{
			"group_value":      r.GroupValue,
			"user_count":       r.UserCount,
			"total_activities": r.TotalActivities,
		}
	}
	return result, nil
}

// placeholders returns a string with n comma-separated '?' placeholders.
func placeholders(n int) string {
	if n <= 0 {
		return ""
	}
	b := make([]byte, 0, n*2-1)
	for i := 0; i < n; i++ {
		if i > 0 {
			b = append(b, ',')
		}
		b = append(b, '?')
	}
	return string(b)
}

