}

// RegisterUser creates a new user profile and inserts it into the database.
func RegisterUser(o orm.Ormer, username, displayName, email, department, role string) (*UserProfile, error) {
	profile := &UserProfile{
		Username:    username,
		DisplayName: displayName,
		Email:       email,
		Department:  department,
		Role:        role,
	}
	// Insert with Ormer.Insert, which will handle auto_now_add and auto pk
	_, err := o.Insert(profile)
	if err != nil {
		return nil, err
	}
	return profile, nil
}

// GenerateUserActivityReport creates an activity report for specified users.
func GenerateUserActivityReport(o orm.Ormer, usernames []string, actionTypeFilter string, startDate, endDate time.Time) ([]UserActivitySummary, error) {
	if len(usernames) == 0 {
		return []UserActivitySummary{}, nil
	}

	// Build IN clause placeholders
	placeholders := strings.Repeat("?,", len(usernames)-1) + "?"
	where := "WHERE u.username IN (" + placeholders + ") AND a.created_at BETWEEN ? AND ?"

	args := make([]interface{}, 0, len(usernames)+3)
	for _, name := range usernames {
		args = append(args, name)
	}
	args = append(args, startDate, endDate)

	if actionTypeFilter != "" {
		where += " AND a.action_type = ?"
		args = append(args, actionTypeFilter)
	}

	query := `SELECT u.display_name, a.action_type, 
		COUNT(*) AS total_actions, 
		SUM(CASE WHEN a.success THEN 1 ELSE 0 END) AS success_count, 
		AVG(a.duration_ms) AS avg_duration
	FROM user_activity a 
	JOIN user_profile u ON a.user_id = u.id
	` + where + `
	GROUP BY u.display_name, a.action_type`

	var summaries []UserActivitySummary
	_, err := o.Raw(query, args...).QueryRows(&summaries)
	if err != nil {
		return nil, err
	}
	// Ensure we return empty slice, not nil, for zero results
	if summaries == nil {
		summaries = []UserActivitySummary{}
	}
	return summaries, nil
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	// Validate and map groupByField to a column expression to avoid SQL injection
	var groupCol string
	switch groupByField {
	case "department":
		groupCol = "u.department"
	case "role":
		groupCol = "u.role"
	case "display_name":
		groupCol = "u.display_name"
	default:
		return nil, orm.ErrMissPK
	}

	// IN clause for departments
	placeholders := strings.Repeat("?,", len(departments)-1) + "?"
	args := make([]interface{}, 0, len(departments))
	for _, dept := range departments {
		args = append(args, dept)
	}

	query := `SELECT ` + groupCol + ` AS group_value, 
		COUNT(DISTINCT u.id) AS user_count, 
		COUNT(a.id) AS total_activities
	FROM user_profile u
	LEFT JOIN user_activity a ON u.id = a.user_id
	WHERE u.department IN (` + placeholders + `)
	GROUP BY ` + groupCol

	var params []orm.Params
	_, err := o.Raw(query, args...).Values(&params)
	if err != nil {
		return nil, err
	}

	// Convert orm.Params to []map[string]interface{}
	result := make([]map[string]interface{}, len(params))
	for i, p := range params {
		result[i] = map[string]interface{}(p)
	}
	return result, nil
}

