		args[i] = dept
	}

	// Build SQL
	sql := fmt.Sprintf(`
		SELECT
			u.%s as group_value,
			COUNT(DISTINCT u.id) as user_count,
			COUNT(a.id) as total_activities
		FROM user_profile u
