	if err != nil {
		return nil, err
	}

	result := make([]map[string]interface{}, len(rows))
	for i, row := range rows {
		m := make(map[string]interface{})
		for k, v := range row {
			m[k] = v
		}
		result[i] = m
	}
	return result, nil
}

